import sys, json
sys.path.insert(0,'/tmp/probe')
from probe import probe
from model import short, predict
pats = dict(short)
r = json.load(open('/tmp/probe/dict_res.json'))
cache = dict(r)
def get(names):
    need = [n for n in names if n not in cache]
    if need:
        res = probe(need)
        for n in need:
            cache[n] = res.get(n, '?')
    return {n: cache[n] for n in names}
for it in range(10):
    bad = [n for n, s in cache.items() if s != '?' and predict(n, pats) != s]
    print("iter", it, "bad", len(bad), "pats", len(pats))
    if not bad: break
    # gather suffixes
    sufs = set()
    for n in bad:
        for i in range(len(n)):
            s = n[i:]
            if len(s) >= 2: sufs.add(s)
    get(list(sufs))
    # for each bad name, find minimal discrepant suffix
    newp = {}
    for n in bad:
        for L in range(1, len(n)+1):
            s = n[-L:]
            st = cache.get(s)
            if st is None or st == '?': continue
            if predict(s, pats) != st:
                newp[s] = st
                break
    print(" new", len(newp))
    pats.update(newp)
