//! Filters applied to search results (size, owner, time).

use std::ffi::CString;
use std::fs::Metadata;
use std::os::unix::fs::MetadataExt;
use std::time::SystemTime;

// ---------------------------------------------------------------------------
// Size filter
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SizeFilter {
    Max(u64),
    Min(u64),
    Equals(u64),
}

impl SizeFilter {
    pub fn from_string(s: &str) -> Option<SizeFilter> {
        let bytes = s.as_bytes();
        let (kind, rest) = match bytes.first() {
            Some(b'+') => ('+', &s[1..]),
            Some(b'-') => ('-', &s[1..]),
            _ => (' ', s),
        };
        // digits
        let digit_end = rest
            .char_indices()
            .find(|(_, c)| !c.is_numeric())
            .map(|(i, _)| i)
            .unwrap_or(rest.len());
        if digit_end == 0 {
            return None;
        }
        let num_str = &rest[..digit_end];
        let unit = rest[digit_end..].to_ascii_lowercase();
        let multiplier: u64 = match unit.as_str() {
            "b" => 1,
            "k" | "kb" => 1000,
            "ki" | "kib" => 1024,
            "m" | "mb" => 1000 * 1000,
            "mi" | "mib" => 1024 * 1024,
            "g" | "gb" => 1000 * 1000 * 1000,
            "gi" | "gib" => 1024 * 1024 * 1024,
            "t" | "tb" => 1000 * 1000 * 1000 * 1000,
            "ti" | "tib" => 1024 * 1024 * 1024 * 1024,
            _ => return None,
        };
        let quantity: u64 = num_str.parse().ok()?;
        let limit = quantity.wrapping_mul(multiplier);
        Some(match kind {
            '+' => SizeFilter::Min(limit),
            '-' => SizeFilter::Max(limit),
            _ => SizeFilter::Equals(limit),
        })
    }

    pub fn is_within(&self, size: u64) -> bool {
        match *self {
            SizeFilter::Max(limit) => size <= limit,
            SizeFilter::Min(limit) => size >= limit,
            SizeFilter::Equals(limit) => size == limit,
        }
    }
}

// ---------------------------------------------------------------------------
// Owner filter
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Check {
    Equal(u32),
    NotEq(u32),
    Ignore,
}

impl Check {
    fn matches(&self, v: u32) -> bool {
        match *self {
            Check::Equal(x) => v == x,
            Check::NotEq(x) => v != x,
            Check::Ignore => true,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OwnerFilter {
    uid: Check,
    gid: Check,
}

fn lookup_user(name: &str) -> Option<u32> {
    let c = CString::new(name).ok()?;
    unsafe {
        let pw = libc::getpwnam(c.as_ptr());
        if pw.is_null() {
            None
        } else {
            Some((*pw).pw_uid)
        }
    }
}

fn lookup_group(name: &str) -> Option<u32> {
    let c = CString::new(name).ok()?;
    unsafe {
        let gr = libc::getgrnam(c.as_ptr());
        if gr.is_null() {
            None
        } else {
            Some((*gr).gr_gid)
        }
    }
}

impl OwnerFilter {
    pub fn from_string(input: &str) -> Result<OwnerFilter, String> {
        let mut parts = input.split(':');
        let user_part = parts.next().unwrap_or("");
        let group_part = parts.next();
        if parts.next().is_some() {
            return Err(format!(
                "more than one ':' present in owner string '{}'. See 'fd --help'.",
                input
            ));
        }
        let uid = Self::parse_part(user_part, true)?;
        let gid = match group_part {
            Some(g) => Self::parse_part(g, false)?,
            None => Check::Ignore,
        };
        Ok(OwnerFilter { uid, gid })
    }

    fn parse_part(s: &str, user: bool) -> Result<Check, String> {
        if s.is_empty() {
            return Ok(Check::Ignore);
        }
        let (negate, name) = match s.strip_prefix('!') {
            Some(rest) => (true, rest),
            None => (false, s),
        };
        let id = if let Ok(id) = name.parse::<u32>() {
            id
        } else if user {
            lookup_user(name)
                .ok_or_else(|| format!("'{}' is not a recognized user name", name))?
        } else {
            lookup_group(name)
                .ok_or_else(|| format!("'{}' is not a recognized group name", name))?
        };
        Ok(if negate {
            Check::NotEq(id)
        } else {
            Check::Equal(id)
        })
    }

    pub fn is_noop(&self) -> bool {
        self.uid == Check::Ignore && self.gid == Check::Ignore
    }

    pub fn matches(&self, md: &Metadata) -> bool {
        self.uid.matches(md.uid()) && self.gid.matches(md.gid())
    }
}

// ---------------------------------------------------------------------------
// Time filter
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug)]
pub enum TimeFilter {
    Before(SystemTime),
    After(SystemTime),
}

impl TimeFilter {
    fn parse_time(s: &str, now: &jiff::Zoned) -> Option<SystemTime> {
        use jiff::{civil::DateTime, Span, Timestamp};

        if let Ok(span) = s.parse::<Span>() {
            let then = now.checked_sub(span).ok()?;
            return Some(SystemTime::from(then.timestamp()));
        }
        if let Ok(ts) = s.parse::<Timestamp>() {
            return Some(SystemTime::from(ts));
        }
        if let Ok(dt) = s.parse::<DateTime>() {
            let zoned = dt.to_zoned(now.time_zone().clone()).ok()?;
            return Some(SystemTime::from(zoned.timestamp()));
        }
        if let Some(rest) = s.strip_prefix('@') {
            if rest.is_empty() || !rest.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            let secs: i64 = rest.parse().ok()?;
            let ts = Timestamp::from_second(secs).ok()?;
            return Some(SystemTime::from(ts));
        }
        None
    }

    pub fn before(s: &str, now: &jiff::Zoned) -> Option<TimeFilter> {
        Self::parse_time(s, now).map(TimeFilter::Before)
    }

    pub fn after(s: &str, now: &jiff::Zoned) -> Option<TimeFilter> {
        Self::parse_time(s, now).map(TimeFilter::After)
    }

    pub fn applies_to(&self, t: &SystemTime) -> bool {
        match self {
            TimeFilter::Before(limit) => t < limit,
            TimeFilter::After(limit) => t > limit,
        }
    }
}

// ---------------------------------------------------------------------------
// File types
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default)]
pub struct FileTypes {
    pub files: bool,
    pub directories: bool,
    pub symlinks: bool,
    pub block_devices: bool,
    pub char_devices: bool,
    pub sockets: bool,
    pub pipes: bool,
    pub executables_only: bool,
    pub empty_only: bool,
}
