//! Parsing of `LS_COLORS` and computing styles for paths.

use std::collections::HashMap;
use std::fs::Metadata;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::Path;

use crate::default_colors::DEFAULT_SUFFIXES;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Named(u8),
    Fixed(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Style {
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strikethrough: bool,
    pub fg: Option<Color>,
    pub bg: Option<Color>,
}

impl Style {
    /// Parse an ANSI SGR sequence like `01;34`. Returns `None` for an empty
    /// or reset-only value, or if the sequence could not be parsed.
    pub fn from_ansi_sequence(code: &str) -> Option<Style> {
        if code.is_empty() || code == "0" || code == "00" {
            return None;
        }
        let mut parts = Vec::new();
        for p in code.split(';') {
            parts.push(p.parse::<u8>().ok()?);
        }
        let mut style = Style::default();
        let mut iter = parts.into_iter();
        while let Some(n) = iter.next() {
            match n {
                0 => {
                    let fg = style.fg;
                    let bg = style.bg;
                    style = Style::default();
                    style.fg = fg;
                    style.bg = bg;
                }
                1 => style.bold = true,
                2 => style.dimmed = true,
                3 => style.italic = true,
                4 => style.underline = true,
                5 | 6 => style.blink = true,
                7 => style.reverse = true,
                8 => style.hidden = true,
                9 => style.strikethrough = true,
                22 => {
                    style.bold = false;
                    style.dimmed = false;
                }
                23 => style.italic = false,
                24 => style.underline = false,
                25 => style.blink = false,
                27 => style.reverse = false,
                28 => style.hidden = false,
                29 => style.strikethrough = false,
                30..=37 => style.fg = Some(Color::Named(n - 30)),
                38 => style.fg = Some(parse_extended(&mut iter)?),
                39 => style.fg = None,
                40..=47 => style.bg = Some(Color::Named(n - 40)),
                48 => style.bg = Some(parse_extended(&mut iter)?),
                49 => style.bg = None,
                90..=97 => style.fg = Some(Color::Fixed(n - 90 + 8)),
                100..=107 => style.bg = Some(Color::Fixed(n - 100 + 8)),
                _ => {}
            }
        }
        Some(style)
    }

    pub fn is_plain(&self) -> bool {
        *self == Style::default()
    }

    /// The ANSI escape prefix for this style (empty if plain).
    pub fn prefix(&self) -> String {
        if self.is_plain() {
            return String::new();
        }
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".into());
        }
        if self.dimmed {
            codes.push("2".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        if self.blink {
            codes.push("5".into());
        }
        if self.reverse {
            codes.push("7".into());
        }
        if self.hidden {
            codes.push("8".into());
        }
        if self.strikethrough {
            codes.push("9".into());
        }
        if let Some(bg) = self.bg {
            codes.push(color_code(bg, true));
        }
        if let Some(fg) = self.fg {
            codes.push(color_code(fg, false));
        }
        format!("\x1b[{}m", codes.join(";"))
    }

    pub fn paint(&self, text: &str) -> String {
        if self.is_plain() {
            text.to_string()
        } else {
            format!("{}{}\x1b[0m", self.prefix(), text)
        }
    }
}

fn color_code(c: Color, bg: bool) -> String {
    let base = if bg { 4 } else { 3 };
    match c {
        Color::Named(n) => format!("{}{}", base, n),
        Color::Fixed(n) => format!("{}8;5;{}", base, n),
        Color::Rgb(r, g, b) => format!("{}8;2;{};{};{}", base, r, g, b),
    }
}

fn parse_extended(iter: &mut impl Iterator<Item = u8>) -> Option<Color> {
    match iter.next()? {
        5 => Some(Color::Fixed(iter.next()?)),
        2 => {
            let r = iter.next()?;
            let g = iter.next()?;
            let b = iter.next()?;
            Some(Color::Rgb(r, g, b))
        }
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Indicator {
    Normal,
    RegularFile,
    Directory,
    SymbolicLink,
    FIFO,
    Socket,
    Door,
    BlockDevice,
    CharacterDevice,
    OrphanedSymbolicLink,
    Setuid,
    Setgid,
    Sticky,
    OtherWritable,
    StickyAndOtherWritable,
    ExecutableFile,
    MissingFile,
    Capabilities,
    MultipleHardLinks,
}

impl Indicator {
    fn from(s: &str) -> Option<Indicator> {
        Some(match s {
            "no" => Indicator::Normal,
            "fi" => Indicator::RegularFile,
            "di" => Indicator::Directory,
            "ln" => Indicator::SymbolicLink,
            "pi" => Indicator::FIFO,
            "so" => Indicator::Socket,
            "do" => Indicator::Door,
            "bd" => Indicator::BlockDevice,
            "cd" => Indicator::CharacterDevice,
            "or" => Indicator::OrphanedSymbolicLink,
            "su" => Indicator::Setuid,
            "sg" => Indicator::Setgid,
            "st" => Indicator::Sticky,
            "ow" => Indicator::OtherWritable,
            "tw" => Indicator::StickyAndOtherWritable,
            "ex" => Indicator::ExecutableFile,
            "mi" => Indicator::MissingFile,
            "ca" => Indicator::Capabilities,
            "mh" => Indicator::MultipleHardLinks,
            _ => return None,
        })
    }
}

