impl LsColors {
    fn empty() -> LsColors {
        LsColors {
            indicators: HashMap::new(),
            regular_file_explicit: false,
            suffixes: Vec::new(),
        }
    }

    fn with_builtin_defaults() -> LsColors {
        let mut c = LsColors::empty();
        c.add_from_string(BUILTIN_DEFAULTS);
        c.regular_file_explicit = false;
        c
    }

    pub fn from_string(input: &str) -> LsColors {
        let mut c = LsColors::with_builtin_defaults();
        c.add_from_string(input);
        c.finish();
        c
    }

    pub fn fd_default() -> LsColors {
        let mut c = LsColors::with_builtin_defaults();
        c.add_from_string(FD_DEFAULT_INDICATORS);
        for (suffix, style) in DEFAULT_SUFFIXES {
            c.suffixes
                .push((suffix.to_string(), Style::from_ansi_sequence(style), false));
        }
        c.finish();
        c
    }

    fn add_from_string(&mut self, input: &str) {
        for entry in input.split(':') {
            let mut parts = entry.split('=');
            let key = match parts.next() {
                Some(k) => k,
                None => continue,
            };
            let value = match parts.next() {
                Some(v) => v,
                None => continue,
            };
            let style = Style::from_ansi_sequence(value);
            if let Some(suffix) = key.strip_prefix('*') {
                self.suffixes.push((suffix.to_string(), style, false));
            } else if let Some(ind) = Indicator::from(key) {
