        let n = self.suffixes.len();
        for i in 0..n {
            let mut cs = false;
            for j in 0..n {
                if i != j
                    && self.suffixes[i].0.eq_ignore_ascii_case(&self.suffixes[j].0)
                    && self.suffixes[i].0 != self.suffixes[j].0
                {
                    cs = true;
                    break;
