        }
        self.indicators.get(&Indicator::Normal)
    }

    fn style_for_suffix(&self, name: &str) -> Option<Option<&Style>> {
        let lower = name.to_ascii_lowercase();
        for (suffix, style, case_sensitive) in self.suffixes.iter().rev() {
            let matched = if *case_sensitive {
                name.ends_with(suffix.as_str())
            } else {
                lower.ends_with(&suffix.to_ascii_lowercase())
            };
            if matched {
                return Some(style.as_ref());
            }
        }
        None
    }

    fn indicator_for(&self, path: &Path, md: Option<&Metadata>) -> Indicator {
        let md = match md {
            Some(md) => md,
            None => return Indicator::Normal,
        };
        let ft = md.file_type();
        let mode = md.permissions().mode();
        if ft.is_dir() {
            let sticky = mode & 0o1000 != 0;
            let other_writable = mode & 0o002 != 0;
            if sticky && other_writable && self.has(Indicator::StickyAndOtherWritable) {
                Indicator::StickyAndOtherWritable
            } else if other_writable && self.has(Indicator::OtherWritable) {
                Indicator::OtherWritable
            } else if sticky && self.has(Indicator::Sticky) {
                Indicator::Sticky
            } else {
                Indicator::Directory
            }
        } else if ft.is_symlink() {
            if self.has(Indicator::OrphanedSymbolicLink) && std::fs::metadata(path).is_err() {
                Indicator::OrphanedSymbolicLink
            } else {
