            } else if md.nlink() > 1 && self.has(Indicator::MultipleHardLinks) {
                Indicator::MultipleHardLinks
            } else {
                Indicator::RegularFile
            }
        } else {
            Indicator::Normal
        }
    }

    pub fn style_for_path_with_metadata(&self, path: &Path, md: Option<&Metadata>) -> Option<&Style> {
        let ind = self.indicator_for(path, md);
