fn push_text(tokens: &mut Vec<Token>, bytes: &[u8]) {
    if bytes.is_empty() {
        return;
    }
    if let Some(Token::Text(t)) = tokens.last_mut() {
        t.extend_from_slice(bytes);
    } else {
        tokens.push(Token::Text(bytes.to_vec()));
    }
}

impl FormatTemplate {
    pub fn parse(input: &OsStr) -> FormatTemplate {
        let s = input.as_bytes();
        let mut tokens: Vec<Token> = Vec::new();
        let mut has_placeholder = false;
        let mut i = 0;
        while i < s.len() {
            let rest = &s[i..];
            if rest.starts_with(b"{{") {
                push_text(&mut tokens, b"{");
                i += 2;
                continue;
            }
            if rest.starts_with(b"}}") {
                push_text(&mut tokens, b"}");
                i += 2;
                continue;
            }
            let placeholders: [(&[u8], Token); 5] = [
                (b"{}", Token::Placeholder),
                (b"{/}", Token::Basename),
                (b"{//}", Token::Parent),
                (b"{.}", Token::NoExt),
                (b"{/.}", Token::BasenameNoExt),
            ];
            let mut matched = false;
            for (pat, tok) in placeholders.iter() {
                if rest.starts_with(pat) {
                    tokens.push(tok.clone());
                    has_placeholder = true;
                    i += pat.len();
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            push_text(&mut tokens, &s[i..i + 1]);
            i += 1;
        }
        if has_placeholder {
            FormatTemplate::Tokens(tokens)
        } else {
            let mut text = Vec::new();
            for t in tokens {
                if let Token::Text(b) = t {
                    text.extend_from_slice(&b);
                }
            }
            FormatTemplate::Text(text)
        }
    }

    pub fn has_tokens(&self) -> bool {
        matches!(self, FormatTemplate::Tokens(_))
    }

    /// Generate the result string for the given path.
    pub fn generate(&self, path: &Path, path_separator: Option<&str>) -> OsString {
        match self {
            FormatTemplate::Text(t) => OsString::from_vec(t.clone()),
            FormatTemplate::Tokens(tokens) => {
                let mut out: Vec<u8> = Vec::new();
                for tok in tokens {
                    match tok {
                        Token::Text(t) => out.extend_from_slice(t),
                        Token::Placeholder => {
                            out.extend_from_slice(&replace_sep(path.as_os_str(), path_separator))
                        }
                        Token::Basename => {
                            out.extend_from_slice(&replace_sep(basename(path), path_separator))
                        }
                        Token::Parent => out.extend_from_slice(&replace_sep(
                            dirname(path).as_os_str(),
                            path_separator,
                        )),
                        Token::NoExt => out.extend_from_slice(&replace_sep(
                            remove_extension(path).as_os_str(),
                            path_separator,
                        )),
                        Token::BasenameNoExt => out.extend_from_slice(&replace_sep(
                            remove_extension(Path::new(basename(path))).as_os_str(),
                            path_separator,
                        )),
                    }
                }
                OsString::from_vec(out)
            }
        }
    }
}

fn replace_sep(s: &OsStr, sep: Option<&str>) -> Vec<u8> {
    match sep {
        None => s.as_bytes().to_vec(),
        Some(sep) => {
            let mut out = Vec::new();
            for &b in s.as_bytes() {
                if b == b'/' {
                    out.extend_from_slice(sep.as_bytes());
                } else {
                    out.push(b);
                }
            }
            out
        }
    }
}

pub fn basename(path: &Path) -> &OsStr {
    path.file_name().unwrap_or(path.as_os_str())
}

pub fn dirname(path: &Path) -> PathBuf {
    match path.parent() {
        Some(p) if p.as_os_str().is_empty() => PathBuf::from("."),
        Some(p) => p.to_path_buf(),
        None => path.to_path_buf(),
    }
}

/// Remove the leading `./` of a path.
pub fn strip_current_dir(path: &Path) -> &Path {
    let mut comps = path.components();
    if comps.next() == Some(Component::CurDir) {
        comps.as_path()
    } else {
        path
    }
}

pub fn remove_extension(path: &Path) -> PathBuf {
    let dirname = path.parent().unwrap_or_else(|| Path::new(""));
    let stem = match path.file_stem() {
        Some(s) => s,
        None => return path.to_path_buf(),
    };
    let joined = dirname.join(stem);
    strip_current_dir(&joined).to_path_buf()
}
