            mode: ExecutionMode::Batch,
            commands,
        })
    }

    pub fn in_batch_mode(&self) -> bool {
        self.mode == ExecutionMode::Batch
    }

    /// Execute all commands for a single path.
    pub fn execute(
        &self,
        path: &Path,
        sep: Option<&str>,
        out_lock: &Mutex<()>,
        buffer_output: bool,
        null_separator: bool,
    ) -> ExitCode {
