enum RunResult {
    Ok(bool, Option<(Vec<u8>, Vec<u8>)>),
    Err(String, Option<(Vec<u8>, Vec<u8>)>),
}

fn flush_outputs(outputs: &mut Vec<(Vec<u8>, Vec<u8>)>) {
    let stdout = io::stdout();
    let stderr = io::stderr();
    for (out, err) in outputs.drain(..) {
        {
            let mut l = stdout.lock();
            let _ = l.write_all(&out);
            let _ = l.flush();
        }
        {
            let mut l = stderr.lock();
            let _ = l.write_all(&err);
            let _ = l.flush();
        }
    }
}

fn command_name(cmd: &Command) -> String {
    cmd.get_program().to_string_lossy().into_owned()
}

fn spawn_error(cmd: &Command, err: &io::Error) -> String {
    if err.kind() == io::ErrorKind::NotFound {
        format!("Command not found: {}", command_name(cmd))
    } else {
        format!("Problem while executing command: {}", err)
    }
}

fn run_command(cmd: &mut Command, buffer_output: bool) -> RunResult {
    if buffer_output {
        cmd.stdin(Stdio::null());
        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::piped());
        match cmd.output() {
            Ok(output) => RunResult::Ok(
                output.status.success(),
                Some((output.stdout, output.stderr)),
            ),
            Err(e) => RunResult::Err(spawn_error(cmd, &e), None),
        }
    } else {
        let _ = io::stdout().flush();
        match cmd.status() {
            Ok(status) => RunResult::Ok(status.success(), None),
            Err(e) => RunResult::Err(spawn_error(cmd, &e), None),
        }
    }
}

fn arg_max_limit() -> usize {
    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    let arg_max: usize = if arg_max <= 0 { 128 * 1024 } else { arg_max as usize };
    let mut env_size = 0usize;
    for (k, v) in std::env::vars_os() {
        env_size += k.as_bytes().len() + v.as_bytes().len() + 2 + std::mem::size_of::<usize>();
    }
    let limit = arg_max.saturating_sub(env_size).saturating_sub(4096);
    limit.min(arg_max / 2).max(4096)
}

fn execute_batch_template(
    template: &CommandTemplate,
    paths: &[PathBuf],
    sep: Option<&str>,
    batch_size: usize,
) -> ExitCode {
    let limit = arg_max_limit();
    let program = template.args[0].generate(Path::new(""), sep);
    let fixed_size = |a: &OsStr| a.as_bytes().len() + 1 + std::mem::size_of::<usize>();

    let mut code = ExitCode::Success;
    let mut start = 0;
    if paths.is_empty() {
        return ExitCode::Success;
    }
    while start < paths.len() {
        // determine chunk
        let mut size = fixed_size(&program);
        for a in &template.args[1..] {
            if !a.has_tokens() {
                size += fixed_size(&a.generate(Path::new(""), sep));
            }
        }
        let mut end = start;
        while end < paths.len() {
            if batch_size > 0 && end - start >= batch_size {
                break;
            }
            let mut item = 0;
            for a in &template.args[1..] {
                if a.has_tokens() {
                    item += fixed_size(&a.generate(&paths[end], sep));
                }
            }
            if end > start && size + item > limit {
                break;
            }
            size += item;
            end += 1;
        }
        let chunk = &paths[start..end];
        let mut cmd = Command::new(&program);
        for a in &template.args[1..] {
            if a.has_tokens() {
                for p in chunk {
                    cmd.arg(a.generate(p, sep));
                }
            } else {
                cmd.arg(a.generate(Path::new(""), sep));
            }
        }
        let _ = io::stdout().flush();
        match cmd.status() {
            Ok(status) => {
                if !status.success() {
                    code = ExitCode::GeneralError;
                }
            }
            Err(e) => {
                print_error(&spawn_error(&cmd, &e));
                code = ExitCode::GeneralError;
            }
        }
        start = end;
    }
    code
}
