use crate::config::Config;
use crate::dir_entry::DirEntry;
use crate::fmt::{strip_current_dir, FormatTemplate};
use crate::lscolors::{Indicator, LsColors, Style};

pub fn absolute_path_for(path: &Path, cwd: &Path) -> PathBuf {
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        let p = path.strip_prefix(".").unwrap_or(path);
        cwd.join(p)
    }
}

fn percent_encode(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len());
    for &b in bytes {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' | b'/' | b':' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn hyperlink_start(path: &Path, config: &Config) -> Vec<u8> {
    let abs = absolute_path_for(path, &config.cwd);
    let host = config.hostname.as_deref().unwrap_or("");
    let mut v = Vec::new();
    v.extend_from_slice(b"\x1b]8;;file://");
    v.extend_from_slice(host.as_bytes());
    v.extend_from_slice(percent_encode(abs.as_os_str().as_bytes()).as_bytes());
    v.extend_from_slice(b"\x1b\\");
    v
}

const HYPERLINK_END: &[u8] = b"\x1b]8;;\x1b\\";

pub fn print_entry<W: Write>(out: &mut W, entry: &DirEntry, config: &Config) -> io::Result<()> {
    let path = if config.strip_cwd_prefix {
        strip_current_dir(entry.path())
    } else {
        entry.path()
    };

    if config.hyperlink {
        out.write_all(&hyperlink_start(path, config))?;
    }

    if let Some(ref format) = config.format {
        print_entry_format(out, path, config, format)?;
    } else if let Some(ref ls_colors) = config.ls_colors {
        print_entry_colorized(out, path, entry, config, ls_colors)?;
    } else {
        print_entry_uncolorized(out, path, entry, config)?;
    }

    if config.hyperlink {
        out.write_all(HYPERLINK_END)?;
    }

    if config.null_separator {
        out.write_all(b"\0")
    } else {
        out.write_all(b"\n")
    }
}

fn print_entry_format<W: Write>(
    out: &mut W,
    path: &Path,
    config: &Config,
    format: &FormatTemplate,
) -> io::Result<()> {
    let s = format.generate(path, config.path_separator.as_deref());
    out.write_all(s.as_bytes())
}

fn replace_separator<'a>(s: &'a str, sep: Option<&str>) -> Cow<'a, str> {
    match sep {
        Some(sep) if s.contains('/') => Cow::Owned(s.replace('/', sep)),
        _ => Cow::Borrowed(s),
    }
}

fn print_entry_colorized<W: Write>(
    out: &mut W,
    path: &Path,
    entry: &DirEntry,
    config: &Config,
    ls_colors: &LsColors,
) -> io::Result<()> {
    let path_str = path.to_string_lossy();
    let sep = config.path_separator.as_deref();

    let dir_style: Style = ls_colors
        .style_for_indicator(Indicator::Directory)
        .copied()
        .unwrap_or_default();

    let (parent, file_name) = match path_str.rfind('/') {
        Some(idx) => (&path_str[..idx + 1], &path_str[idx + 1..]),
        None => ("", &path_str[..]),
    };

    if !parent.is_empty() {
        let p = replace_separator(parent, sep);
        out.write_all(dir_style.paint(&p).as_bytes())?;
    }

    let style = ls_colors
        .style_for_path_with_metadata(path, entry.metadata())
        .copied()
        .unwrap_or_default();
    out.write_all(style.paint(file_name).as_bytes())?;

    if entry.is_dir() {
        out.write_all(dir_style.paint(&config.actual_path_separator).as_bytes())?;
    }
    Ok(())
}

fn print_entry_uncolorized<W: Write>(
    out: &mut W,
    path: &Path,
    entry: &DirEntry,
    config: &Config,
) -> io::Result<()> {
    match config.path_separator {
        Some(ref sep) => {
            let s = path.to_string_lossy();
            out.write_all(s.replace('/', sep).as_bytes())?;
        }
        None => out.write_all(path.as_os_str().as_bytes())?,
    }
    if entry.is_dir() {
        out.write_all(config.actual_path_separator.as_bytes())?;
    }
    Ok(())
}
