use std::cmp::Ordering;
use std::fs::{FileType, Metadata};
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

enum Inner {
    Normal(ignore::DirEntry),
    BrokenSymlink(PathBuf),
}

pub struct DirEntry {
    inner: Inner,
    metadata: OnceLock<Option<Metadata>>,
}

impl DirEntry {
    pub fn normal(e: ignore::DirEntry) -> DirEntry {
        DirEntry {
            inner: Inner::Normal(e),
            metadata: OnceLock::new(),
        }
    }

    pub fn broken_symlink(path: PathBuf) -> DirEntry {
        DirEntry {
            inner: Inner::BrokenSymlink(path),
            metadata: OnceLock::new(),
        }
    }

    pub fn path(&self) -> &Path {
        match &self.inner {
            Inner::Normal(e) => e.path(),
            Inner::BrokenSymlink(p) => p,
        }
    }

    pub fn into_path(self) -> PathBuf {
        match self.inner {
            Inner::Normal(e) => e.into_path(),
            Inner::BrokenSymlink(p) => p,
        }
    }

    pub fn file_type(&self) -> Option<FileType> {
        match &self.inner {
            Inner::Normal(e) => e.file_type(),
            Inner::BrokenSymlink(_) => self.metadata().map(|m| m.file_type()),
        }
    }

    pub fn metadata(&self) -> Option<&Metadata> {
        self.metadata
            .get_or_init(|| match &self.inner {
                Inner::Normal(e) => e.metadata().ok(),
                Inner::BrokenSymlink(p) => p.symlink_metadata().ok(),
            })
            .as_ref()
    }

    pub fn depth(&self) -> Option<usize> {
        match &self.inner {
            Inner::Normal(e) => Some(e.depth()),
            Inner::BrokenSymlink(_) => None,
        }
    }

    pub fn is_dir(&self) -> bool {
        self.file_type().map(|t| t.is_dir()).unwrap_or(false)
    }
}

impl PartialEq for DirEntry {
    fn eq(&self, other: &Self) -> bool {
        self.path() == other.path()
    }
}

impl Eq for DirEntry {}

impl PartialOrd for DirEntry {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for DirEntry {
    fn cmp(&self, other: &Self) -> Ordering {
        self.path().cmp(other.path())
    }
}
