//! Directory traversal and result processing.

use std::ffi::OsStr;
use std::io::{self, Write};
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

use crossbeam_channel::{bounded, Receiver, RecvTimeoutError, Sender};
use ignore::overrides::OverrideBuilder;
use ignore::{WalkBuilder, WalkParallel, WalkState};
use regex::bytes::Regex;

use crate::config::Config;
use crate::dir_entry::DirEntry;
use crate::error::print_error;
use crate::exit_codes::{merge_exitcodes, ExitCode};
use crate::output;

const MAX_BUFFER_LENGTH: usize = 1000;
const DEFAULT_MAX_BUFFER_TIME: Duration = Duration::from_millis(100);

pub enum WorkerResult {
    Entry(DirEntry),
    Error(ignore::Error),
}

pub fn scan(paths: &[PathBuf], patterns: Vec<Regex>, config: Config) -> anyhow::Result<ExitCode> {
    let config = Arc::new(config);
    let patterns = Arc::new(patterns);

    let first_path = &paths[0];

    let mut override_builder = OverrideBuilder::new(first_path);
    for pattern in &config.exclude_patterns {
        if let Err(e) = override_builder.add(pattern) {
            anyhow::bail!("Malformed exclude pattern: {}", e);
        }
    }
    let overrides = override_builder
        .build()
        .map_err(|_| anyhow::anyhow!("Mismatch in exclude patterns"))?;

    let mut builder = WalkBuilder::new(first_path);
    builder
        .hidden(config.ignore_hidden)
        .ignore(config.read_fdignore)
        .parents(config.read_parent_ignore && (config.read_fdignore || config.read_vcsignore))
        .git_ignore(config.read_vcsignore)
        .git_global(config.read_vcsignore)
        .git_exclude(config.read_vcsignore)
        .require_git(config.require_git_to_read_vcsignore)
        .overrides(overrides)
        .follow_links(config.follow_links)
        .same_file_system(config.one_file_system)
        .max_depth(config.max_depth);

    if config.read_fdignore {
        builder.add_custom_ignore_filename(".fdignore");
    }

    if config.read_global_ignore {
        if let Some(global) = global_ignore_file() {
            if global.is_file() {
                if let Some(err) = builder.add_ignore(&global) {
                    print_error(format!("Malformed pattern in global ignore file. {}.", err));
                }
            }
        }
    }

    for ignore_file in &config.ignore_files {
        if let Some(err) = builder.add_ignore(ignore_file) {
            print_error(format!("Malformed pattern in custom ignore file. {}.", err));
        }
    }

    for path in &paths[1..] {
        builder.add(path);
    }

    let parallel_walker = builder.threads(config.threads).build_parallel();

    let quit_flag = Arc::new(AtomicBool::new(false));
    let interrupt_flag = Arc::new(AtomicBool::new(false));

    let (tx, rx) = bounded::<WorkerResult>(0x4000);

    let receiver_config = Arc::clone(&config);
    let receiver_quit = Arc::clone(&quit_flag);
    let receiver_interrupt = Arc::clone(&interrupt_flag);
    let receiver_thread = thread::spawn(move || {
        receive(rx, receiver_config, receiver_quit, receiver_interrupt)
    });

    spawn_senders(&config, &quit_flag, patterns, parallel_walker, tx);

    let exit_code = receiver_thread.join().unwrap();
    Ok(exit_code)
}

fn global_ignore_file() -> Option<PathBuf> {
    let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
        Some(x) if Path::new(&x).is_absolute() => Some(PathBuf::from(x)),
        _ => std::env::var_os("HOME")
            .filter(|h| !h.is_empty())
            .map(|h| PathBuf::from(h).join(".config")),
    }?;
    Some(config_dir.join("fd").join("ignore"))
}

// ---------------------------------------------------------------------------
// Receiver
// ---------------------------------------------------------------------------

#[derive(PartialEq, Eq)]
enum ReceiverMode {
    Buffering,
    Streaming,
}

struct ReceiverBuffer<'a, W: Write> {
    config: &'a Config,
    quit_flag: &'a AtomicBool,
    interrupt_flag: &'a AtomicBool,
    rx: Receiver<WorkerResult>,
    mode: ReceiverMode,
    deadline: Instant,
    buffer: Vec<DirEntry>,
    stdout: W,
    num_results: usize,
}

enum Stop {
    Exit(ExitCode),
}

impl<'a, W: Write> ReceiverBuffer<'a, W> {
    fn process(&mut self) -> ExitCode {
        loop {
            if let Err(Stop::Exit(code)) = self.poll() {
                self.quit_flag.store(true, Ordering::Relaxed);
                return code;
            }
        }
    }

    fn recv(&self) -> Result<WorkerResult, RecvTimeoutError> {
        match self.mode {
            ReceiverMode::Buffering => self.rx.recv_deadline(self.deadline),
            ReceiverMode::Streaming => self.rx.recv().map_err(|_| RecvTimeoutError::Disconnected),
        }
    }

    fn poll(&mut self) -> Result<(), Stop> {
        match self.recv() {
            Ok(WorkerResult::Entry(entry)) => {
                if self.config.quiet {
                    return Err(Stop::Exit(ExitCode::HasResults(true)));
                }
                match self.mode {
                    ReceiverMode::Buffering => {
                        self.buffer.push(entry);
                        if self.buffer.len() > MAX_BUFFER_LENGTH {
                            self.stream()?;
                        }
                    }
                    ReceiverMode::Streaming => {
                        self.print(&entry)?;
                    }
                }
                self.num_results += 1;
                if let Some(max) = self.config.max_results {
                    if self.num_results >= max {
                        return self.stop();
                    }
                }
            }
            Ok(WorkerResult::Error(err)) => {
                if self.config.show_filesystem_errors {
                    print_error(err);
                }
            }
            Err(RecvTimeoutError::Timeout) => {
                self.stream()?;
            }
            Err(RecvTimeoutError::Disconnected) => {
                return self.stop();
            }
        }
        Ok(())
    }

    fn print(&mut self, entry: &DirEntry) -> Result<(), Stop> {
        if let Err(e) = output::print_entry(&mut self.stdout, entry, self.config) {
            if e.kind() == io::ErrorKind::BrokenPipe {
                return Err(Stop::Exit(ExitCode::Success));
            }
            print_error(format!("Could not write to output: {}", e));
            return Err(Stop::Exit(ExitCode::GeneralError));
        }
        if self.interrupt_flag.load(Ordering::Relaxed) {
            return Err(Stop::Exit(ExitCode::KilledBySigint));
        }
        if self.mode == ReceiverMode::Streaming && self.config.interactive_flush() {
            self.flush()?;
        }
        Ok(())
    }

    fn stream(&mut self) -> Result<(), Stop> {
        self.mode = ReceiverMode::Streaming;
        let buffer = std::mem::take(&mut self.buffer);
        for entry in buffer {
            self.print(&entry)?;
        }
        self.flush()
    }

    fn stop(&mut self) -> Result<(), Stop> {
        if self.mode == ReceiverMode::Buffering {
            self.buffer.sort();
            self.stream()?;
        }
        if self.config.quiet {
            Err(Stop::Exit(ExitCode::HasResults(self.num_results > 0)))
        } else {
            self.flush()?;
            Err(Stop::Exit(ExitCode::Success))
        }
    }

    fn flush(&mut self) -> Result<(), Stop> {
        if let Err(e) = self.stdout.flush() {
            if e.kind() == io::ErrorKind::BrokenPipe {
                return Err(Stop::Exit(ExitCode::Success));
            }
            print_error(format!("Could not write to output: {}", e));
            return Err(Stop::Exit(ExitCode::GeneralError));
        }
        Ok(())
    }
}

impl Config {
    fn interactive_flush(&self) -> bool {
        self.interactive_terminal
    }
}

fn receive(
    rx: Receiver<WorkerResult>,
    config: Arc<Config>,
    quit_flag: Arc<AtomicBool>,
    interrupt_flag: Arc<AtomicBool>,
) -> ExitCode {
    if let Some(ref cmd) = config.command {
        if cmd.in_batch_mode() {
            // Collect all results, then run the command(s).
            let mut paths: Vec<PathBuf> = Vec::new();
            for result in rx.iter() {
                match result {
                    WorkerResult::Entry(entry) => paths.push(prepare_path(entry.into_path(), &config)),
                    WorkerResult::Error(err) => {
                        if config.show_filesystem_errors {
                            print_error(err);
                        }
                    }
                }
            }
            if paths.is_empty() {
                return ExitCode::Success;
            }
            return cmd.execute_batch(&paths, config.path_separator.as_deref(), config.batch_size);
        } else {
            let out_lock = Arc::new(Mutex::new(()));
            let threads = config.threads;
            let buffer_output = threads > 1;
            let mut handles = Vec::new();
            for _ in 0..threads {
                let rx = rx.clone();
                let config = Arc::clone(&config);
                let cmd = Arc::clone(cmd);
                let out_lock = Arc::clone(&out_lock);
                handles.push(thread::spawn(move || {
                    let mut results: Vec<ExitCode> = Vec::new();
                    for result in rx.iter() {
                        match result {
                            WorkerResult::Entry(entry) => {
                                let path = prepare_path(entry.into_path(), &config);
                                let code = cmd.execute(
                                    &path,
                                    config.path_separator.as_deref(),
                                    &out_lock,
                                    buffer_output,
                                    config.null_separator,
                                );
                                results.push(code);
                            }
                            WorkerResult::Error(err) => {
                                if config.show_filesystem_errors {
                                    print_error(err);
                                }
                            }
                        }
                    }
                    merge_exitcodes(results)
                }));
            }
            drop(rx);
            let codes: Vec<ExitCode> = handles.into_iter().map(|h| h.join().unwrap()).collect();
            let _ = io::stdout().flush();
            return merge_exitcodes(codes);
        }
    }

    let start = Instant::now();
    let max_buffer_time = config.max_buffer_time.unwrap_or(DEFAULT_MAX_BUFFER_TIME);
    let stdout = io::stdout();
    let lock = stdout.lock();
    let writer = io::BufWriter::new(lock);
    let mut rb = ReceiverBuffer {
        config: &config,
        quit_flag: &quit_flag,
        interrupt_flag: &interrupt_flag,
        rx,
        mode: ReceiverMode::Buffering,
        deadline: start + max_buffer_time,
        buffer: Vec::with_capacity(MAX_BUFFER_LENGTH),
        stdout: writer,
        num_results: 0,
    };
    rb.process()
}

fn prepare_path(path: PathBuf, config: &Config) -> PathBuf {
    if config.strip_cwd_prefix {
        crate::fmt::strip_current_dir(&path).to_path_buf()
    } else {
        path
    }
}

// ---------------------------------------------------------------------------
// Senders
// ---------------------------------------------------------------------------

fn spawn_senders(
    config: &Arc<Config>,
    quit_flag: &Arc<AtomicBool>,
    patterns: Arc<Vec<Regex>>,
    parallel_walker: WalkParallel,
    tx: Sender<WorkerResult>,
) {
    parallel_walker.run(|| {
        let config = Arc::clone(config);
        let patterns = Arc::clone(&patterns);
        let tx_thread = tx.clone();
        let quit_flag = Arc::clone(quit_flag);

        Box::new(move |entry_o| {
            if quit_flag.load(Ordering::Relaxed) {
                return WalkState::Quit;
            }

            let entry = match entry_o {
                Ok(e) => {
                    if e.depth() == 0 {
                        // The root directory itself: only check ignore-contain.
                        if !config.ignore_contain.is_empty()
                            && contains_ignored_entry(e.path(), &config)
                        {
                            return WalkState::Skip;
                        }
                        return WalkState::Continue;
                    }
                    DirEntry::normal(e)
                }
                Err(ignore::Error::WithPath { path, err: inner_err }) => {
                    let is_broken_symlink = match inner_err.as_ref() {
                        ignore::Error::Io(io_error) => {
                            io_error.kind() == io::ErrorKind::NotFound
                                && path
                                    .symlink_metadata()
                                    .map(|m| m.file_type().is_symlink())
                                    .unwrap_or(false)
                        }
                        _ => false,
                    };
                    if is_broken_symlink {
                        DirEntry::broken_symlink(path)
                    } else {
                        return match tx_thread.send(WorkerResult::Error(ignore::Error::WithPath {
                            path,
                            err: inner_err,
                        })) {
                            Ok(_) => WalkState::Continue,
                            Err(_) => WalkState::Quit,
                        };
                    }
                }
                Err(err) => {
                    return match tx_thread.send(WorkerResult::Error(err)) {
                        Ok(_) => WalkState::Continue,
                        Err(_) => WalkState::Quit,
                    };
                }
            };

            if !config.ignore_contain.is_empty() && contains_ignored_entry(entry.path(), &config) {
                return WalkState::Skip;
            }

            if let Some(min_depth) = config.min_depth {
                if entry.depth().map_or(true, |d| d < min_depth) {
                    return WalkState::Continue;
                }
            }

            // Check the name first, since it doesn't require metadata
            let entry_path = entry.path();

            let search_str: std::borrow::Cow<OsStr> = if config.search_full_path {
                let abs = output::absolute_path_for(entry_path, &config.cwd);
                std::borrow::Cow::Owned(abs.into_os_string())
            } else {
                match entry_path.file_name() {
                    Some(filename) => std::borrow::Cow::Borrowed(filename),
                    None => unreachable!("Invalid file name: {:?}", entry_path),
                }
            };

            if !patterns
                .iter()
                .all(|pat| pat.is_match(search_str.as_bytes()))
            {
                return WalkState::Continue;
            }

            // Filter out unwanted extensions.
            if let Some(ref exts_regex) = config.extensions {
                if let Some(path_str) = entry_path.file_name() {
                    if !exts_regex.is_match(path_str.as_bytes()) {
                        return WalkState::Continue;
                    }
                } else {
                    return WalkState::Continue;
                }
            }

            // Filter out unwanted file types.
            if let Some(ref file_types) = config.file_types {
                if should_ignore_type(file_types, &entry) {
                    return WalkState::Continue;
                }
            }

            if let Some(ref owner_constraint) = config.owner_constraint {
                if let Some(metadata) = entry.metadata() {
                    if !owner_constraint.matches(metadata) {
                        return WalkState::Continue;
                    }
                } else {
                    return WalkState::Continue;
                }
            }

            // Filter out unwanted sizes if it is a file and we have been given size constraints.
            if !config.size_constraints.is_empty() {
                if entry_path.is_file() || entry.file_type().map_or(false, |t| t.is_file()) {
                    if let Some(metadata) = entry.metadata() {
                        let file_size = metadata.len();
                        if config
                            .size_constraints
                            .iter()
                            .any(|sc| !sc.is_within(file_size))
                        {
                            return WalkState::Continue;
                        }
                    } else {
                        return WalkState::Continue;
                    }
                } else {
                    return WalkState::Continue;
                }
            }

            // Filter out unwanted modification times
            if !config.time_constraints.is_empty() {
                let mut matched = false;
                if let Some(metadata) = entry.metadata() {
                    if let Ok(modified) = metadata.modified() {
                        matched = config
                            .time_constraints
                            .iter()
                            .all(|tf| tf.applies_to(&modified));
                    }
                }
                if !matched {
                    return WalkState::Continue;
                }
            }

            let is_dir = entry.is_dir();

            let send_result = tx_thread.send(WorkerResult::Entry(entry));

            if send_result.is_err() {
                return WalkState::Quit;
            }

            // Apply pruning.
            if config.prune && is_dir {
                return WalkState::Skip;
            }

            WalkState::Continue
        })
    });
}

fn contains_ignored_entry(path: &Path, config: &Config) -> bool {
    config
        .ignore_contain
        .iter()
        .any(|name| path.join(name).exists())
}

fn is_executable(path: &Path) -> bool {
    let c = match std::ffi::CString::new(path.as_os_str().as_bytes()) {
        Ok(c) => c,
        Err(_) => return false,
    };
    unsafe { libc::faccessat(libc::AT_FDCWD, c.as_ptr(), libc::X_OK, libc::AT_EACCESS) == 0 }
}

fn is_empty(entry: &DirEntry) -> bool {
    if let Some(file_type) = entry.file_type() {
        if file_type.is_dir() {
            if let Ok(mut entries) = std::fs::read_dir(entry.path()) {
                entries.next().is_none()
            } else {
                false
            }
        } else if file_type.is_file() {
            entry.metadata().map(|m| m.len() == 0).unwrap_or(false)
        } else {
            false
        }
    } else {
        false
    }
}

fn should_ignore_type(ft: &crate::filter::FileTypes, entry: &DirEntry) -> bool {
    use std::os::unix::fs::FileTypeExt;
    if let Some(entry_type) = entry.file_type() {
        (!ft.files && entry_type.is_file())
            || (!ft.directories && entry_type.is_dir())
            || (!ft.symlinks && entry_type.is_symlink())
            || (!ft.sockets && entry_type.is_socket())
            || (!ft.pipes && entry_type.is_fifo())
            || (!ft.char_devices && entry_type.is_char_device())
            || (!ft.block_devices && entry_type.is_block_device())
            || (ft.executables_only && !is_executable(entry.path()))
            || (ft.empty_only && !is_empty(entry))
            || !(entry_type.is_file()
                || entry_type.is_dir()
                || entry_type.is_symlink()
                || entry_type.is_socket()
                || entry_type.is_fifo()
                || entry_type.is_char_device()
                || entry_type.is_block_device())
    } else {
        true
    }
}
