            {
                return WalkState::Continue;
            }

            // Filter out unwanted extensions.
            if let Some(ref exts_regex) = config.extensions {
                if let Some(path_str) = entry_path.file_name() {
                    if !exts_regex.is_match(path_str.as_bytes()) {
                        return WalkState::Continue;
                    }
                } else {
                    return WalkState::Continue;
                }
            }

            // Filter out unwanted file types.
            if let Some(ref file_types) = config.file_types {
                if should_ignore_type(file_types, &entry) {
                    return WalkState::Continue;
                }
            }

            if let Some(ref owner_constraint) = config.owner_constraint {
                if let Some(metadata) = entry.metadata() {
                    if !owner_constraint.matches(metadata) {
                        return WalkState::Continue;
                    }
                } else {
                    return WalkState::Continue;
                }
            }

            // Filter out unwanted sizes if it is a file and we have been given size constraints.
            if !config.size_constraints.is_empty() {
                if entry_path.is_file() || entry.file_type().map_or(false, |t| t.is_file()) {
                    if let Some(metadata) = entry.metadata() {
                        let file_size = metadata.len();
                        if config
                            .size_constraints
                            .iter()
                            .any(|sc| !sc.is_within(file_size))
                        {
                            return WalkState::Continue;
                        }
                    } else {
                        return WalkState::Continue;
                    }
                } else {
                    return WalkState::Continue;
                }
            }

            // Filter out unwanted modification times
            if !config.time_constraints.is_empty() {
                let mut matched = false;
                if let Some(metadata) = entry.metadata() {
                    if let Ok(modified) = metadata.modified() {
                        matched = config
                            .time_constraints
                            .iter()
                            .all(|tf| tf.applies_to(&modified));
                    }
                }
                if !matched {
                    return WalkState::Continue;
                }
            }

            let is_dir = entry.is_dir();

            let send_result = tx_thread.send(WorkerResult::Entry(entry));

            if send_result.is_err() {
                return WalkState::Quit;
            }

            // Apply pruning.
            if config.prune && is_dir {
                return WalkState::Skip;
            }

            WalkState::Continue
        })
    });
}

fn contains_ignored_entry(path: &Path, config: &Config) -> bool {
    config
        .ignore_contain
        .iter()
        .any(|name| path.join(name).exists())
}

fn is_executable(path: &Path) -> bool {
    let c = match std::ffi::CString::new(path.as_os_str().as_bytes()) {
        Ok(c) => c,
        Err(_) => return false,
    };
    unsafe { libc::faccessat(libc::AT_FDCWD, c.as_ptr(), libc::X_OK, libc::AT_EACCESS) == 0 }
}

fn is_empty(entry: &DirEntry) -> bool {
    if let Some(file_type) = entry.file_type() {
        if file_type.is_dir() {
            if let Ok(mut entries) = std::fs::read_dir(entry.path()) {
                entries.next().is_none()
            } else {
                false
            }
        } else if file_type.is_file() {
            entry.metadata().map(|m| m.len() == 0).unwrap_or(false)
        } else {
            false
        }
    } else {
        false
    }
}

fn should_ignore_type(ft: &crate::filter::FileTypes, entry: &DirEntry) -> bool {
    use std::os::unix::fs::FileTypeExt;
    if let Some(entry_type) = entry.file_type() {
        (!ft.files && entry_type.is_file())
            || (!ft.directories && entry_type.is_dir())
            || (!ft.symlinks && entry_type.is_symlink())
            || (!ft.sockets && entry_type.is_socket())
            || (!ft.pipes && entry_type.is_fifo())
            || (!ft.char_devices && entry_type.is_char_device())
            || (!ft.block_devices && entry_type.is_block_device())
            || (ft.executables_only && !is_executable(entry.path()))
            || (ft.empty_only && !is_empty(entry))
            || !(entry_type.is_file()
                || entry_type.is_dir()
                || entry_type.is_symlink()
                || entry_type.is_socket()
                || entry_type.is_fifo()
                || entry_type.is_char_device()
                || entry_type.is_block_device())
    } else {
        true
    }
}
