    if matches.contains_id("gen_completions") && matches.value_source("gen_completions").is_some() {
        return generate_completions(&matches);
    }

    set_working_dir(&matches)?;
    let search_paths = search_paths(&matches)?;

    let pattern: &str = matches
        .get_one::<String>("pattern")
        .map(|s| s.as_str())
        .unwrap_or("");
    let full_path = matches.get_flag("full_path");
    if !full_path && pattern.contains('/') && Path::new(pattern).is_dir() {
        bail!(
            "The search pattern '{pattern}' contains a path-separation character ('/') \
             and will not lead to any search results.\n\n\
             If you want to search for all files inside the '{pattern}' directory, use a match-all pattern:\n\n  \
             fd . '{pattern}'\n\n\
             Instead, if you want your pattern to match the full file path, use:\n\n  \
             fd --full-path '{pattern}'",
            pattern = pattern
        );
    }

    let mut exprs: Vec<String> = vec![pattern.to_string()];
    if let Some(ands) = matches.get_many::<String>("exprs") {
        exprs.extend(ands.cloned());
    }

    let glob = matches.get_flag("glob");
    let fixed = matches.get_flag("fixed_strings");
    let pattern_regexps: Vec<String> = exprs
        .iter()
        .map(|pat| build_pattern_regex(pat, glob, fixed, full_path))
        .collect::<anyhow::Result<Vec<String>>>()?;

    let config = construct_config(&matches, &pattern_regexps)?;

    let regexps = pattern_regexps
        .iter()
        .map(|pat| build_regex(pat, &config))
        .collect::<anyhow::Result<Vec<_>>>()?;

    walk::scan(&search_paths, regexps, config)
}

fn generate_completions(matches: &ArgMatches) -> anyhow::Result<ExitCode> {
    use clap_complete::Shell;
    let shell: Shell = match matches.get_one::<String>("gen_completions") {
        Some(s) => s.parse().map_err(|e: String| anyhow!(e))?,
        None => Shell::from_env().ok_or_else(|| anyhow!("Unable to get shell from environment"))?,
    };
    let mut cmd = cli::build_command();
    let name = bin_name();
    let mut out = io::stdout().lock();
    clap_complete::generate(shell, &mut cmd, name, &mut out);
    Ok(ExitCode::Success)
}

fn set_working_dir(matches: &ArgMatches) -> anyhow::Result<()> {
    if let Some(base_directory) = matches.get_one::<PathBuf>("base_directory") {
        let base_directory = Path::new(base_directory);
        if !base_directory.is_dir() {
            bail!(
                "The '--base-directory' path '{}' is not a directory.",
                base_directory.to_string_lossy()
            );
        }
        env::set_current_dir(base_directory).with_context(|| {
            format!(
                "Could not set '{}' as the current working directory",
                base_directory.to_string_lossy()
            )
        })?;
    }
    Ok(())
}

fn is_current_dir(p: &Path) -> bool {
    p == Path::new(".")
}

fn search_paths(matches: &ArgMatches) -> anyhow::Result<Vec<PathBuf>> {
    let paths: Option<Vec<PathBuf>> = matches
        .get_many::<PathBuf>("path")
        .or_else(|| matches.get_many::<PathBuf>("search_path"))
        .map(|p| p.cloned().collect());
    let paths = match paths {
        Some(p) => p,
        None => vec![PathBuf::from(".")],
    };
    let absolute = matches.get_flag("absolute_path");
    let mut result = Vec::new();
    for path in paths {
        if !path.is_dir() {
            print_error(format!(
                "Search path '{}' is not a directory.",
                path.to_string_lossy()
            ));
            continue;
        }
        let path = if is_current_dir(&path) {
            PathBuf::from(".")
        } else {
            path
        };
        let path = if absolute {
            match std::fs::canonicalize(&path) {
                Ok(p) => p,
                Err(_) => path,
            }
        } else {
            path
        };
        result.push(path);
    }
    if result.is_empty() {
        bail!("No valid search paths given.");
    }
    Ok(result)
}

fn build_pattern_regex(pattern: &str, glob: bool, fixed: bool, full_path: bool) -> anyhow::Result<String> {
    Ok(if glob && !pattern.is_empty() {
        let g = GlobBuilder::new(pattern)
            .literal_separator(full_path)
            .build()
            .map_err(|e| anyhow!("{}", e))?;
        g.regex().to_owned()
    } else if fixed {
        regex::escape(pattern)
    } else {
        pattern.to_owned()
    })
}

fn build_regex(pattern_regex: &str, config: &Config) -> anyhow::Result<regex::bytes::Regex> {
    RegexBuilder::new(pattern_regex)
        .case_insensitive(!config.case_sensitive)
        .dot_matches_new_line(true)
        .build()
        .map_err(|e| {
            anyhow!(
                "{}\n\nNote: You can use the '--fixed-strings' option to search for a \
                 literal string instead of a regular expression. Alternatively, you can \
                 also use the '--glob' option to match on a glob pattern.",
                e
            )
        })
}

fn color_enabled(matches: &ArgMatches) -> bool {
    match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") => true,
        Some("never") => false,
        _ => {
            let no_color = env::var_os("NO_COLOR").map_or(false, |v| !v.is_empty());
            io::stdout().is_terminal() && !no_color
        }
    }
}

fn hostname() -> Option<String> {
    let mut buf = vec![0u8; 256];
    let r = unsafe { libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
    if r != 0 {
        return None;
    }
    let end = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    buf.truncate(end);
    String::from_utf8(buf).ok()
}

fn num_threads(matches: &ArgMatches) -> usize {
    if let Some(n) = matches.get_one::<std::num::NonZeroUsize>("threads") {
        return n.get();
    }
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
}

fn get_exec_commands(matches: &ArgMatches, id: &str) -> Option<Vec<Vec<OsString>>> {
    let occ = matches.get_occurrences::<OsString>(id)?;
    Some(occ.map(|o| o.cloned().collect()).collect())
}

fn construct_config(matches: &ArgMatches, pattern_regexps: &[String]) -> anyhow::Result<Config> {
    let unrestricted = matches.get_count("rg_alias_hidden_ignore") > 0;
    let no_ignore = matches.get_flag("no_ignore") || unrestricted;
    let hidden = matches.get_flag("hidden") || unrestricted;

    let case_sensitive = if matches.get_flag("case_sensitive") {
        true
    } else if matches.get_flag("ignore_case") {
        false
    } else {
        pattern_regexps.iter().any(|p| pattern_has_uppercase_char(p))
    };

    let colored_output = color_enabled(matches);
    let ls_colors = if colored_output {
        Some(match env::var("LS_COLORS") {
            Ok(val) => LsColors::from_string(&val),
            Err(_) => LsColors::fd_default(),
        })
    } else {
        None
    };

    let hyperlink = match matches.get_one::<String>("hyperlink").map(|s| s.as_str()) {
        Some("always") => true,
        Some("auto") => colored_output,
        _ => false,
    };

    let null_separator = matches.get_flag("null_separator");
    let list_details = matches.get_flag("list_details");

    let command: Option<CommandSet> = if let Some(cmds) = get_exec_commands(matches, "exec") {
        Some(CommandSet::new(cmds))
    } else if let Some(cmds) = get_exec_commands(matches, "exec_batch") {
        match CommandSet::new_batch(cmds) {
            Ok(c) => Some(c),
            Err(msg) => clap_error(&msg),
        }
    } else if list_details {
        let color_arg = if colored_output {
            "--color=always"
        } else {
            "--color=never"
        };
        let cmd: Vec<OsString> = ["ls", "-l", "-h", "-d", color_arg]
            .iter()
            .map(OsString::from)
            .collect();
        Some(CommandSet::new_batch(vec![cmd]).map_err(|e| anyhow!(e))?)
    } else {
        None
    };

    let size_constraints: Vec<SizeFilter> = matches
        .get_many::<SizeFilter>("size")
        .map(|v| v.copied().collect())
        .unwrap_or_default();

    let now = jiff::Zoned::now();
    let mut time_constraints: Vec<TimeFilter> = Vec::new();
    if let Some(t) = matches.get_one::<String>("changed_within") {
        match TimeFilter::after(t, &now) {
            Some(f) => time_constraints.push(f),
            None => bail!("'{}' is not a valid date or duration. See 'fd --help'.", t),
        }
    }
    if let Some(t) = matches.get_one::<String>("changed_before") {
        match TimeFilter::before(t, &now) {
            Some(f) => time_constraints.push(f),
            None => bail!("'{}' is not a valid date or duration. See 'fd --help'.", t),
        }
    }

    let owner_constraint: Option<OwnerFilter> = matches
        .get_one::<OwnerFilter>("owner")
        .copied()
        .filter(|o| !o.is_noop());

    let file_types = matches.get_many::<String>("filetype").map(|values| {
        let mut ft = FileTypes::default();
        for v in values {
            match v.as_str() {
                "file" | "f" => ft.files = true,
                "directory" | "d" | "dir" => ft.directories = true,
                "symlink" | "l" => ft.symlinks = true,
                "block-device" | "b" => ft.block_devices = true,
                "char-device" | "c" => ft.char_devices = true,
                "executable" | "x" => {
                    ft.executables_only = true;
                    ft.files = true;
                }
                "empty" | "e" => ft.empty_only = true,
                "socket" | "s" => ft.sockets = true,
                "pipe" | "p" => ft.pipes = true,
                _ => {}
            }
        }
        if ft.empty_only && !(ft.files || ft.directories) {
            ft.files = true;
            ft.directories = true;
        }
        ft
    });

    let extensions = match matches.get_many::<String>("extensions") {
        Some(exts) => {
            let patterns: Vec<String> = exts
                .map(|e| e.trim_start_matches('.'))
                .map(|e| format!(r"^.+\.{}$", regex::escape(e)))
                .collect();
            Some(
                RegexSetBuilder::new(patterns)
                    .case_insensitive(true)
                    .build()
                    .map_err(|e| anyhow!("{}", e))?,
            )
        }
        None => None,
    };

    let format = matches
        .get_one::<String>("format")
        .map(|f| FormatTemplate::parse(f.as_ref()));

    let path_separator = matches.get_one::<String>("path_separator").cloned();
    let actual_path_separator = path_separator.clone().unwrap_or_else(|| "/".to_string());

    let max_results = if matches.get_flag("max_one_result") {
        Some(1)
    } else {
        matches.get_one::<usize>("max_results").copied().filter(|&m| m > 0)
    };

    let implicit_search_path = matches.get_many::<PathBuf>("path").is_none()
        && matches.get_many::<PathBuf>("search_path").is_none();
    let strip_cwd_prefix = implicit_search_path
        && match matches.get_one::<String>("strip_cwd_prefix").map(|s| s.as_str()) {
            Some("always") => true,
            Some("never") => false,
            _ => !(null_separator || command.is_some()),
        };

    let exact_depth = matches.get_one::<usize>("exact_depth").copied();
    let max_depth = exact_depth.or_else(|| matches.get_one::<usize>("max_depth").copied());
    let min_depth = exact_depth.or_else(|| matches.get_one::<usize>("min_depth").copied());

    let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));

    Ok(Config {
        case_sensitive,
        search_full_path: matches.get_flag("full_path"),
        ignore_hidden: !hidden,
        read_fdignore: !no_ignore,
        read_vcsignore: !(no_ignore || matches.get_flag("no_ignore_vcs")),
        require_git_to_read_vcsignore: !matches.get_flag("no_require_git"),
        read_parent_ignore: !matches.get_flag("no_ignore_parent"),
        read_global_ignore: !(no_ignore || matches.get_flag("no_global_ignore_file")),
        follow_links: matches.get_flag("follow"),
        one_file_system: matches.get_flag("one_file_system"),
        null_separator,
        max_depth,
        min_depth,
        prune: matches.get_flag("prune"),
        threads: num_threads(matches),
        quiet: matches.get_flag("quiet"),
        max_buffer_time: matches
            .get_one::<u64>("max_buffer_time")
            .map(|&ms| Duration::from_millis(ms)),
        ls_colors,
        hyperlink,
        file_types,
        extensions,
        format,
        command: command.map(Arc::new),
        batch_size: matches.get_one::<usize>("batch_size").copied().unwrap_or(0),
        exclude_patterns: matches
            .get_many::<String>("exclude")
            .map(|v| v.map(|p| format!("!{}", p)).collect())
            .unwrap_or_default(),
        ignore_files: matches
            .get_many::<PathBuf>("ignore_file")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        size_constraints,
        time_constraints,
        owner_constraint,
        show_filesystem_errors: matches.get_flag("show_errors"),
        path_separator,
        actual_path_separator,
        max_results,
        strip_cwd_prefix,
        ignore_contain: matches
            .get_many::<String>("ignore_contain")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        cwd,
        hostname: hostname(),
        interactive_terminal: io::stdout().is_terminal(),
    })
}
