/// Determine whether a regex pattern can only match strings that start with a dot.
pub fn pattern_matches_strings_with_leading_dot(pattern: &str) -> bool {
    let mut parser = ParserBuilder::new().utf8(false).build();
    parser
        .parse(pattern)
        .map(|hir| hir_matches_strings_with_leading_dot(&hir))
        .unwrap_or(false)
}

fn hir_matches_strings_with_leading_dot(hir: &Hir) -> bool {
    use regex_syntax::hir::Look;
    if let HirKind::Concat(hirs) = hir.kind() {
        let mut iter = hirs.iter();
        if let (Some(first), Some(second)) = (iter.next(), iter.next()) {
            if let HirKind::Look(Look::Start) = first.kind() {
                if let HirKind::Literal(lit) = second.kind() {
                    return lit.0.first() == Some(&b'.');
                }
            }
        }
    }
    false
}
