{"command":"cd /workspace && python3 - <<'EOF'
p='/workspace/src/exec.rs'
s=open(p).read()
start=s.index("    /// Execute the batch commands with all paths.")
end=s.index("enum RunResult {")
new='''    /// Execute the batch commands with all paths.
    pub fn execute_batch(&self, paths: &[PathBuf], sep: Option<&str>, batch_size: usize) -> ExitCode {
        let limit = arg_max_limit();
        let mut builders: Vec<BatchBuilder> = self
            .commands
            .iter()
            .map(|t| BatchBuilder::new(t, sep, batch_size, limit))
            .collect();
        for path in paths {
            for builder in builders.iter_mut() {
                if let Err(()) = builder.push(path) {
                    return ExitCode::GeneralError;
                }
            }
        }
        for builder in builders.iter_mut() {
            if let Err(()) = builder.finish() {
                return ExitCode::GeneralError;
            }
        }
        if builders.iter().any(|b| b.failed) {
            ExitCode::GeneralError
        } else {
            ExitCode::Success
        }
    }
}

struct BatchBuilder<'a> {
    template: &'a CommandTemplate,
    sep: Option<&'a str>,
    batch_size: usize,
    limit: usize,
    base_size: usize,
    current: Vec<OsString>,
    current_size: usize,
    failed: bool,
}

fn arg_size(a: &OsStr) -> usize {
    a.as_bytes().len() + 1 + std::mem::size_of::<usize>()
}

impl<'a> BatchBuilder<'a> {
    fn new(template: &'a CommandTemplate, sep: Option<&'a str>, batch_size: usize, limit: usize) -> Self {
        let mut base_size = 0;
        for a in &template.args {
            if !a.has_tokens() {
                base_size += arg_size(&a.generate(Path::new(""), sep));
            }
        }
        BatchBuilder {
            template,
            sep,
            batch_size,
            limit,
            base_size,
            current: Vec::new(),
            current_size: 0,
            failed: false,
        }
    }

    fn push(&mut self, path: &Path) -> Result<(), ()> {
        let expanded: Vec<OsString> = self.template.args[1..]
            .iter()
            .filter(|a| a.has_tokens())
            .map(|a| a.generate(path, self.sep))
            .collect();
        let size: usize = expanded.iter().map(|a| arg_size(a)).sum();
        let count = self.current.len();
        if count > 0
            && ((self.batch_size > 0 && count >= self.batch_size)
                || self.base_size + self.current_size + size > self.limit)
        {
            self.finish()?;
        }
        for e in expanded {
            self.current.push(e);
        }
        self.current_size += size;
        Ok(())
    }

    fn finish(&mut self) -> Result<(), ()> {
        if self.current.is_empty() {
            return Ok(());
        }
        let items = std::mem::take(&mut self.current);
        self.current_size = 0;
        let program = self.template.args[0].generate(Path::new(""), self.sep);
        let mut cmd = Command::new(&program);
        for a in &self.template.args[1..] {
            if a.has_tokens() {
                for item in &items {
                    cmd.arg(item);
                }
            } else {
                cmd.arg(a.generate(Path::new(""), self.sep));
            }
        }
        match cmd.status() {
            Ok(status) => {
                if !status.success() {
                    self.failed = true;
                }
                Ok(())
            }
            Err(e) => {
                print_error(&spawn_error(&cmd, &e));
                Err(())
            }
        }
    }
